import java.util.*;

class Solution {
    public int widthOfBinaryTree(TreeNode root) {
        Deque<TreeNode> nodes = new ArrayDeque<>();
        Deque<Long> idx = new ArrayDeque<>();
        nodes.add(root);
        idx.add(0L);
        long best = 0;
        while (!nodes.isEmpty()) {
            long first = idx.peekFirst(), last = idx.peekLast();
            best = Math.max(best, last - first + 1);
            int size = nodes.size();
            for (int k = 0; k < size; k++) {
                TreeNode n = nodes.poll();
                long i = idx.poll() - first; // re-base so numbers stay small
                if (n.left != null) { nodes.add(n.left); idx.add(2 * i); }
                if (n.right != null) { nodes.add(n.right); idx.add(2 * i + 1); }
            }
        }
        return (int) best;
    }
}

