class Solution:
    def widthOfBinaryTree(self, root: Optional[TreeNode]) -> int:
        best, q = 0, [(root, 0)]
        while q:
            best = max(best, q[-1][1] - q[0][1] + 1)
            base = q[0][1]; nq = []
            for n, i in q:
                i -= base
                if n.left: nq.append((n.left, 2 * i))
                if n.right: nq.append((n.right, 2 * i + 1))
            q = nq
        return best

